[MenuItem("Tools/Out Scene Transfer/Back Up Grass Edge And Sky Settings")]
public static void Backup(){var b=new StringBuilder();try{var s=Main();var camera=CameraOf(s);string path="Assets/ArtStyleTest/Scenes_BACKUP/out_before_grass_sky_repair_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity";if(!EditorSceneManager.SaveScene(s,path,true))throw new Exception("Backup failed");b.AppendLine("backup="+path);foreach(var n in new[]{"DistantHillGrass.shader","DistantGrassVertex.hlsl","LargerWorldGrass.hlsl"})File.Copy(ShaderRoot+n,W+"Before_GrassSkyRepair_"+n+".txt",true);b.AppendLine("oldSky="+AssetDatabase.GetAssetPath(RenderSettings.skybox));Capture(camera,"Out_grass_sky_repair_before.png");b.AppendLine("backedUp=True");}catch(Exception e){b.AppendLine(e.ToString());}File.WriteAllText(W+"out_grass_sky_repair_backup.txt",b.ToString());}
static void AddPatch(Scene scene,Camera camera,StringBuilder report){if(scene.GetRootGameObjects().Any(g=>g.name=="Meadow Distant Grass Gap Repair"))return;var terrain=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Terrain>(false)).First(t=>t.drawHeightmap&&t.terrainData);var collider=terrain.GetComponent<TerrainCollider>();RaycastHit hit=default;bool found=false;float aspect=camera.aspect;try{camera.aspect=16f/9;for(int k=0;k<8;k++){var ray=camera.ViewportPointToRay(new Vector3(.025f,.505f-k*.006f,0));if(collider.Raycast(ray,out hit,450)&&hit.distance>40){found=true;break;}}}finally{camera.ResetAspect();}if(!found){report.AppendLine("patch=No far terrain hit");return;}
var centre=hit.point;report.AppendLine("bluePatchTerrain="+centre.ToString("F3")+" distance="+hit.distance+" normal="+hit.normal);float radius=13,step=.42f;var vertices=new List<Vector3>();var normals=new List<Vector3>();var uv=new List<Vector4>();var triangles=new List<int>();var origin=terrain.transform.position;var data=terrain.terrainData;Func<float,float,Vector3> point=(x,z)=>new Vector3(x,terrain.SampleHeight(new Vector3(x,0,z))+origin.y+.028f,z);Action<Vector3,Vector3,Vector3,Vector4[]> tri=(a,bb,c,roots)=>{int index=vertices.Count;vertices.Add(a-centre);vertices.Add(bb-centre);vertices.Add(c-centre);for(int i=0;i<3;i++){normals.Add(Vector3.up);uv.Add(roots[i]);triangles.Add(index+i);}};
for(float z=centre.z-radius;z<centre.z+radius;z+=step)for(float x=centre.x-radius;x<centre.x+radius;x+=step){if(new Vector2(x+step*.5f-centre.x,z+step*.5f-centre.z).sqrMagnitude>radius*radius)continue;var a=point(x,z);var bb=point(x+step,z);var c=point(x,z+step);var d=point(x+step,z+step);Func<Vector3,Vector4> root=(p)=>new Vector4(p.x-centre.x,p.y-centre.y,p.z-centre.z,0);tri(a,c,bb,new[]{root(a),root(c),root(bb)});tri(bb,c,d,new[]{root(bb),root(c),root(d)});}
var random=new System.Random(19630);int tufts=0;for(int i=0;i<1700;i++){float x=centre.x+(float)(random.NextDouble()*2-1)*radius,z=centre.z+(float)(random.NextDouble()*2-1)*radius;float edge=new Vector2(x-centre.x,z-centre.z).magnitude/radius;if(edge>.98f||random.NextDouble()>1-Mathf.SmoothStep(.6f,1,edge))continue;var p=point(x,z)+Vector3.up*.014f;float height=.42f+(float)random.NextDouble()*.25f;for(int blade=0;blade<3;blade++){float angle=(float)random.NextDouble()*6.283185f;var side=new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle))*(.17f+(float)random.NextDouble()*.10f);var r=new Vector4(p.x-centre.x,p.y-centre.y,p.z-centre.z,height);tri(p-side,p+side,p+Vector3.up*height,new[]{r,r,r});}tufts++;}
var mesh=new Mesh{name="Distant meadow gap cover",indexFormat=IndexFormat.UInt32};mesh.SetVertices(vertices);mesh.SetNormals(normals);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Folder+"/Distant_Gap_Cover.asset");var go=new GameObject("Meadow Distant Grass Gap Repair",typeof(MeshFilter),typeof(MeshRenderer));SceneManager.MoveGameObjectToScene(go,scene);go.transform.position=centre;go.GetComponent<MeshFilter>().sharedMesh=mesh;var renderer=go.GetComponent<MeshRenderer>();renderer.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/ArtStyleTest/OutAssets/Codex_PainterlyMeadow/DistantHill/DistantHillGrass.mat");renderer.shadowCastingMode=ShadowCastingMode.Off;Undo.RegisterCreatedObjectUndo(go,"Fill distant grass gap");report.AppendLine("patchTufts="+tufts+" patchTriangles="+triangles.Count/3);}
[MenuItem("Tools/Out Scene Transfer/Fix Grass Edges And Enable Cloud Editing")]
public static void Apply(){var b=new StringBuilder();try{var s=Main();if(!File.ReadAllText(W+"out_grass_sky_repair_backup.txt").Contains("backedUp=True"))throw new Exception("Back up first");var camera=CameraOf(s);var roots=s.GetRootGameObjects();var poses=roots.SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToDictionary(t=>t,t=>t.localToWorldMatrix);var visibility=roots.SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToDictionary(r=>r,r=>r.enabled);var terrainStates=roots.SelectMany(g=>g.GetComponentsInChildren<Terrain>(true)).ToDictionary(t=>t,t=>t.drawHeightmap);var lights=roots.SelectMany(g=>g.GetComponentsInChildren<Light>(true)).ToDictionary(l=>l,l=>EditorJsonUtility.ToJson(l));string cameraSettings=EditorJsonUtility.ToJson(camera);string focusSettings=EditorJsonUtility.ToJson(camera.GetComponent<MeadowCameraFocus>());Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var controller=roots.SelectMany(g=>g.GetComponentsInChildren<MeadowGrassDistanceBlend>(true)).FirstOrDefault();if(!controller){var g=new GameObject("Meadow Grass Distance Blend");SceneManager.MoveGameObjectToScene(g,s);controller=g.AddComponent<MeadowGrassDistanceBlend>();Undo.RegisterCreatedObjectUndo(g,"Smooth distant grass edges");}controller.referenceCamera=camera;controller.transitionStart=18;controller.transitionEnd=65;controller.distantHeight=.24f;controller.Apply();EditorUtility.SetDirty(controller);AddPatch(s,camera,b);
var skyPath=Folder+"/Out_EditableSky.mat";var sky=AssetDatabase.LoadAssetAtPath<Material>(skyPath);if(!sky){var old=RenderSettings.skybox;sky=new Material(Shader.Find("Codex/Meadow/EditableSky")){name="Out editable sky and ribbon clouds"};foreach(var key in new[]{"_Zenith","_Horizon","_Cloud"})sky.SetColor(key,old.GetColor(key));AssetDatabase.CreateAsset(sky,skyPath);}RenderSettings.skybox=sky;
foreach(var p in poses){var after=p.Key.localToWorldMatrix;for(int i=0;i<16;i++)if(Mathf.Abs(p.Value[i]-after[i])>.001f)throw new Exception("Original object moved: "+p.Key.name);}foreach(var r in visibility)if(r.Key.enabled!=r.Value)throw new Exception("Renderer visibility changed: "+r.Key.name);foreach(var t in terrainStates)if(t.Key.drawHeightmap!=t.Value)throw new Exception("Terrain display changed");foreach(var light in lights)if(EditorJsonUtility.ToJson(light.Key)!=light.Value)throw new Exception("Light changed");if(cameraSettings!=EditorJsonUtility.ToJson(camera)||focusSettings!=EditorJsonUtility.ToJson(camera.GetComponent<MeadowCameraFocus>()))throw new Exception("Camera or focus changed");int errors=0;foreach(var shader in new[]{Shader.Find("Codex/Meadow/EditableSky"),Shader.Find("Codex/PainterlyMeadow/DistantHillGrass"),Shader.Find("Codex/PainterlyMeadow/WorldGrass")})foreach(var message in ShaderUtil.GetShaderMessages(shader).Where(m=>m.severity.ToString()=="Error")){errors++;b.AppendLine(message.message);}if(errors>0)throw new Exception("Shader errors: "+errors);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);SceneView.RepaintAll();Capture(camera,"Out_grass_edges_cloud_editor_final.png");Selection.activeObject=sky;EditorGUIUtility.PingObject(sky);b.AppendLine("cloudMaterial="+skyPath+" menu=Tools/天空与云朵 nearGrassUnchangedWithin18m=True lightsCameraVisibilityAndOriginalTransformsUnchanged=True shaderErrors="+errors+" saved=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_grass_sky_repair_result.txt",b.ToString());}
